// Validation tổng thể cho bảng
var valid = true;
var errors = [];

// Hàm kiểm tra tổng sản phẩm
function validateTotalProducts(data) {
  // Lợn: 01=02+03+04
  var lonTotal = data.find(item => item.code === '0145200');
  var lonThit = data.find(item => item.code === '01452001');
  var lonNaiDe = data.find(item => item.code === '014520021');
  var lonSua = data.find(item => item.code === '0145120');

  if (lonTotal && (lonThit || lonNaiDe || lonSua)) {
    var calculatedTotal = (parseFloat(lonThit?.totalSlaughtered || 0) + 
                          parseFloat(lonNaiDe?.totalSlaughtered || 0) + 
                          parseFloat(lonSua?.totalSlaughtered || 0));
    var actualTotal = parseFloat(lonTotal.totalSlaughtered || 0);

    if (Math.abs(actualTotal - calculatedTotal) > 0.01 && actualTotal > 0) {
      errors.push('Tổng sản phẩm Lợn đang [lớn hơn/nhỏ hơn] các giá trị con!');
    }
  }

  // Gà: 05=06+09
  var gaTotal = data.find(item => item.code === '0146210');
  var gaThit = data.find(item => item.code === '01462101');
  var gaDeThanhLy = data.find(item => item.code === '01462104');

  if (gaTotal && (gaThit || gaDeThanhLy)) {
    var calculatedGaTotal = (parseFloat(gaThit?.totalSlaughtered || 0) + 
                            parseFloat(gaDeThanhLy?.totalSlaughtered || 0));
    var actualGaTotal = parseFloat(gaTotal.totalSlaughtered || 0);

    if (Math.abs(actualGaTotal - calculatedGaTotal) > 0.01 && actualGaTotal > 0) {
      errors.push('Tổng sản phẩm Gà đang [lớn hơn/nhỏ hơn] các giá trị con!');
    }
  }

  // Gà thịt: 06=07+08
  var gaCongNghiep = data.find(item => item.code === '014621021');
  var gaKhac = data.find(item => item.code === '01462103');

  if (gaThit && (gaCongNghiep || gaKhac)) {
    var calculatedGaThitTotal = (parseFloat(gaCongNghiep?.totalSlaughtered || 0) + 
                                parseFloat(gaKhac?.totalSlaughtered || 0));
    var actualGaThitTotal = parseFloat(gaThit.totalSlaughtered || 0);

    if (Math.abs(actualGaThitTotal - calculatedGaThitTotal) > 0.01 && actualGaThitTotal > 0) {
      errors.push('Tổng sản phẩm Gà thịt đang [lớn hơn/nhỏ hơn] các giá trị con!');
    }
  }

  // Vịt: 10=11+12
  var vitTotal = data.find(item => item.code === '0146310');
  var vitThit = data.find(item => item.code === '01463102');
  var vitDeThanhLy = data.find(item => item.code === '01463103');

  if (vitTotal && (vitThit || vitDeThanhLy)) {
    var calculatedVitTotal = (parseFloat(vitThit?.totalSlaughtered || 0) + 
                             parseFloat(vitDeThanhLy?.totalSlaughtered || 0));
    var actualVitTotal = parseFloat(vitTotal.totalSlaughtered || 0);

    if (Math.abs(actualVitTotal - calculatedVitTotal) > 0.01 && actualVitTotal > 0) {
      errors.push('Tổng sản phẩm Vịt đang [lớn hơn/nhỏ hơn] các giá trị con!');
    }
  }
}

// Kiểm tra ngưỡng cảnh báo 1 triệu con
function checkMillionThreshold(data) {
  var totalProducts = ['0145200', '0146210', '0146310', '0146320'];
  totalProducts.forEach(code => {
    var item = data.find(i => i.code === code);
    if (item && parseFloat(item.totalSlaughtered || 0) >= 1000000) {
      errors.push(`Tổng sản phẩm ${item.name} đang lớn hơn/bằng [ngưỡng cảnh báo]!`);
    }
  });
}

if (input && Array.isArray(input)) {
  validateTotalProducts(input);
  checkMillionThreshold(input);
}

if (errors.length > 0) {
  return errors.join('\n');
}

return valid;

