// Nếu chưa chọn lĩnh vực thì thoát
if (!data.linhVucHoatDong) return;

var grid = instance.root.getComponent('bangSanPhamXuatChuong');
if (!grid) return;

var originalDefaultValue = grid.component.defaultValue || [];
var linhVuc = data.linhVucHoatDong;
var currentData = data.bangSanPhamXuatChuong || [];

// --- Tách dòng mẫu và dữ liệu thực tế ---
var templateRow = originalDefaultValue[0]; // luôn giữ dòng đầu tiên
var dataToFilter = originalDefaultValue.slice(1); // bỏ dòng đầu tiên

// Map dữ liệu nhập để merge lại
var existingDataMap = {};
currentData.forEach(function(item) {
  var key = item.code || ('stt' + item.stt + (item.name || '').substring(0, 10));
  existingDataMap[key] = item;
});

// --- Filter theo lĩnh vực dựa trên type ---
var filtered = [];
if (linhVuc === 'nuoiLon') {
  filtered = dataToFilter.filter(item => item.type === 'Pig');
} else if (linhVuc === 'nuoiGiaCam') {
  filtered = dataToFilter.filter(item => item.type === 'Poultry');
} else if (linhVuc === 'nuoiHonHop') {
  filtered = dataToFilter;
}

// --- Merge dữ liệu nhập + format lại STT ---
var mergedData = filtered.map(function(row, index) {
  var key = row.code || ('stt' + row.stt + (row.name || '').substring(0, 10));
  var existing = existingDataMap[key] || {};
  
  // FIX: Đảm bảo giữ lại parentCode từ dữ liệu gốc
  return Object.assign({}, row, existing, {
    stt: (index + 1).toString().padStart(2, '0'), // 01, 02, 03...
    // Đảm bảo các thuộc tính cấu trúc không bị ghi đè
    parentCode: row.parentCode,
    codeList: row.codeList,
    type: row.type,
    name: row.name,
    code: row.code
  });
});

// --- Ghép lại với dòng mẫu ---
var finalData = [templateRow].concat(mergedData);

// Cập nhật grid
grid.setValue(finalData);

components.customConditional:
// Chỉ in đậm các dòng cấp cao nhất (không có parentCode)
// và các dòng có parentCode trỏ đến dòng cấp cao nhất
var isTopLevel = !row.parentCode || row.parentCode === null;
var isDirectChild = false;

if (!isTopLevel && row.parentCode) {
  // Kiểm tra xem parentCode có phải là dòng cấp cao nhất không
  var parentRow = data.bangSanPhamXuatChuong.find(function(item) {
    return item.code === row.parentCode;
  });
  isDirectChild = parentRow && (!parentRow.parentCode || parentRow.parentCode === null);
}

if (isTopLevel) {
  component.customClass = 'bold-text';
} else {
  component.customClass = '';
}

